/// <reference types="vite/client" />

/**
 * Stamped in by `vite.config.ts`'s `define` at build time.
 *
 * ⚠️ **Declared here or they are not types, they are `any` and a typo.** These are substituted as
 * literals before TypeScript ever sees a value, so nothing else in the project can tell that
 * `__BUILD_HASH__` exists.
 */
declare const __APPLICATION_VERSION__: string
declare const __BUILD_DATE__: string
declare const __BUILD_HASH__: string
declare const __BUILD_ID__: string
